if(!chosen){$('#as-ret-summary').innerHTML=stat('首次行为人数','0','当前筛选没有批次');$('#as-ret-note').textContent='当前筛选没有首次行为用户。';return}
const coSelected=()=>candidates.find(x=>x.d===+$('#as-cohort-picker').value)||chosen;
function renderTable(){
$('#as-cohort-title').textContent=continuous?'连续留存批次表':'日留存批次表';
$('#as-cohort-table').innerHTML=table(['首次日期','D0 人数',...Array.from({length:7},(_,i)=>(continuous?'连续 ':'')+'D'+(i+1))],cohorts.map((co,i)=>[`<button class="a-tablelink cursor-interaction" data-select-co="${co.d}" ${co.users.length?'':'disabled'}>${date(base+co.d*day)}${co.d===coSelected().d?' · 当前':''}</button>`,co.users.length,...Array.from({length:7},(_,j)=>{let d=j+1;if(!co.users.length||!observed(co,d))return '<span class="a-heat-unavailable" title="未到观察期或无入组用户">—</span>';let n=returned(co,d,continuous).length;return `<button class="a-heat cursor-interaction ${mature(co,d)?'is-complete':'is-pending'}" style="--heat-intensity:${Math.round(n/co.users.length*75)+5}%" aria-label="${date(base+co.d*day)} D${d} 留存 ${pct(n,co.users.length)}，${n}人，${mature(co,d)?'观察完成':'进行中'}" data-co="${i}" data-day="${d}">${pct(n,co.users.length)}<small>${n} 人${mature(co,d)?'':' · 进行中'}</small></button>`})]));
$$('[data-select-co]').forEach(b=>b.onclick=()=>{$('#as-cohort-picker').value=b.dataset.selectCo;render()});$$('[data-co]').forEach(b=>b.onclick=()=>{const co=cohorts[+b.dataset.co],n=+b.dataset.day;drill(date(base+co.d*day)+' · '+(continuous?'连续 ':'')+'D'+n,drillRows(returned(co,n,continuous)),`${co.users.length} 位 D0 用户 · 按首次行为来源${mature(co,n)?'':' · 观察进行中'}`)})}
function render(){clearNative();closeDrill();const co=coSelected(),n0=co.users.length;
const d1=returned(co,1).length,seven=co.users.filter(u=>u.events.some(e=>e.type===c.returning&&daynum(e.t)>co.d&&daynum(e.t)<=co.d+7)).length,con7=returned(co,7,true).length;
$('#as-ret-summary').innerHTML=stat('当前批次 D0 人数',fmt(n0),date(base+co.d*day)+' · 首次行为用户')+stat('D1 留存率',observed(co,1)?pct(d1,n0):'—',observed(co,1)?`${d1} / ${n0}${mature(co,1)?' · 完整日':' · 进行中'}`:'尚未到观察日')+stat(continuous?'连续 7 日留存率':'7 日内回访率',mature(co,7)?pct(continuous?con7:seven,n0):'—',mature(co,7)?`${continuous?con7:seven} / ${n0} · 同一批次`:'观察窗口进行中');
$('#as-ret-title').textContent=continuous?'连续留存漏斗':'日留存曲线';$('#as-ret-note').textContent=continuous?'从 D1 起每天都回来才进入下一层；未到观察日的层暂不显示。点击层查看用户。':'每天独立观察，留存率可以回升。点击数据点查看当天回访用户；进行中数据尚未定稿。';
renderTable();const host=$('#as-ret-chart');host.style.height=continuous?'470px':'300px';host.setAttribute('aria-label',continuous?'同一批次连续留存漏斗':'同一批次 D0 到 D7 日留存率曲线');
if(!globalThis.echarts){host.innerHTML='<p class="a-status">图表组件未加载，请稍后运行分析重试。可查看下方批次表。</p>';return}
const color=key=>{const p=document.createElement('span');p.style.color=`var(${key})`;root.appendChild(p);const v=getComputedStyle(p).color;p.remove();return v};
const data=Array.from({length:8},(_,d)=>({d,name:d===0?'D0':(continuous?'连续 ':'')+'D'+d,num:d===0?n0:returned(co,d,continuous).length,ready:d===0||observed(co,d),done:d===0||mature(co,d)}));nativeChart=echarts.init(host,null,{renderer:'svg'});
const paint=()=>{if(!nativeChart||!host.isConnected)return;const tooltip={trigger:'item',confine:true,backgroundColor:color('--a-panel'),borderColor:color('--a-border'),textStyle:{color:color('--a-text')},formatter:p=>{const x=data[p.dataIndex];return `${x.name}<br/>${x.num} / ${n0} 人<br/>${pct(x.num,n0)}<br/>${x.done?'观察已完成':'进行中'}`}};let option;
if(continuous){const dd=data.filter(x=>x.ready);option={animation:false,aria:{enabled:true},tooltip,series:[{type:'funnel',sort:'none',top:10,bottom:10,left:'4%',width:'56%',min:0,max:n0,minSize:'0%',maxSize:'100%',gap:7,label:{show:true,position:'right',color:color('--a-text'),fontSize:12,lineHeight:18,formatter:p=>`${p.name}${dd[p.dataIndex].done?'':' · 进行中'}\n${p.value} 人 · ${pct(p.value,n0)}`},labelLine:{length:12,lineStyle:{color:color('--a-muted'),width:1}},itemStyle:{color:color('--a-accent'),borderWidth:0},data:dd.map(x=>({name:x.name,value:x.num}))}]}}
else{option={animation:false,aria:{enabled:true},tooltip,grid:{left:48,right:28,top:36,bottom:40},xAxis:{type:'category',name:'回访日',nameLocation:'middle',nameGap:26,data:data.map(x=>'D'+x.d),axisLabel:{color:color('--a-muted'),fontSize:12},axisLine:{lineStyle:{color:color('--a-border')}}},yAxis:{type:'value',min:0,max:100,name:'留存率（%）',nameTextStyle:{color:color('--a-muted')},axisLabel:{color:color('--a-muted'),formatter:'{value}%'},splitLine:{lineStyle:{color:color('--a-border')}}},series:[{type:'line',connectNulls:false,symbolSize:9,smooth:false,lineStyle:{color:color('--a-accent'),width:2},itemStyle:{color:color('--a-accent')},data:data.map(x=>({value:x.ready?+(x.num/n0*100).toFixed(1):null,symbol:x.done?'circle':'emptyCircle'}))}]}}
nativeChart.setOption(option,true)};paint();nativeChart.on('click',p=>{const x=data[p.dataIndex];if(!x.ready)return;drill(date(base+co.d*day)+' · '+x.name,drillRows(x.d===0?co.users:returned(co,x.d,continuous)),`D0 ${n0} 人 · 按首次行为来源`)});nativeResize=new ResizeObserver(()=>nativeChart&&nativeChart.resize());nativeResize.observe(host);themeHandler=paint;themeMedia.addEventListener('change',themeHandler)}
$('#as-cohort-picker').onchange=render;$$('[data-retmode]').forEach(b=>b.onclick=()=>{continuous=b.dataset.retmode==='continuous';$$('[data-retmode]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});render();
