function clearTrade(){if(tradeResize){tradeResize.disconnect();tradeResize=null}if(tradeChart){tradeChart.dispose();tradeChart=null}if(tradeTheme){themeMedia.removeEventListener('change',tradeTheme);tradeTheme=null}}
const dailyTrades=isMock?users.flatMap((u,i)=>Array.from({length:14},(_,d)=>{const active=base+(d+1)*day>u.events[0].t,hash=((i+11)*7919+(d+3)*104729)%10007;return {u,date:base+d*day,volume:active&&hash%5!==0?((hash%950)+50)*10:0}})):(dataStore.trades||[]).filter(t=>t.status==='confirmed').map(t=>({u:users.find(u=>u.id===t.user_id)||{id:t.user_id},date:Math.floor((t.confirmed_at+7*3600000)/day)*day-7*3600000,volume:t.volume_usd}));
function tradingContribution(c){const analyzed=new Set(users.filter(u=>u.events.some(e=>e.type==='chip'&&e.t<c.end)).map(u=>u.id));const records=dailyTrades.filter(r=>r.date>=c.start&&r.date<c.end);const days=Array.from({length:c.range},(_,i)=>{const date=c.start+i*day,rs=records.filter(r=>r.date===date);const a=rs.filter(r=>analyzed.has(r.u.id)).reduce((a,r)=>a+r.volume,0),b=rs.filter(r=>!analyzed.has(r.u.id)).reduce((a,r)=>a+r.volume,0);return{date,a,b,total:a+b}});const a=days.reduce((a,d)=>a+d.a,0),b=days.reduce((a,d)=>a+d.b,0);return{analyzed,records,days,a,b,total:a+b}}
const money=n=>'$'+fmt(n);
function tradeMarkup(tx,c){if(!isMock&&!Array.isArray(dataStore.trades))return `<section class="a-card a-details"><h2>交易数据待获取</h2><p>交易接口未提供数据，交易量和贡献占比暂不可用。</p></section>`;return `<section class="a-card" id="as-trade-module"><div class="a-cardhead"><div><h2>有效分析用户交易贡献</h2><p class="a-muted">全平台 · ${date(c.start)}–${date(c.end-day)} · 计价单位 USD</p></div><span class="a-chip">平台总交易量 ${money(tx.total)}</span></div><div class="a-summary" style="border:0;border-radius:0;margin:0">${stat('截至期末有效分析用户交易量',`<button class="a-tablelink cursor-interaction" data-trade-group="a" style="font:inherit">${money(tx.a)}</button>`,'截至期末曾完成有效分析')}${stat('其他用户交易量',`<button class="a-tablelink cursor-interaction" data-trade-group="b" style="font:inherit">${money(tx.b)}</button>`,'截至期末无有效分析记录')}${stat('有效分析用户交易量占比',pct(tx.a,tx.total),'两类用户交易量之和 = 平台总量')}</div><div class="a-chart"><h2>每日交易量构成</h2><div id="as-trade-chart" style="width:100%;height:300px" role="img" aria-label="每日平台交易量堆叠图，区分有效分析用户和其他用户"></div></div><div class="a-insight">按统计期末状态固定分组，包含首次分析前的交易。此模块仅随日期变化，始终展示全平台，不受来源筛选影响。</div><details class="a-details"><summary>每日交易明细与统计口径</summary>${table(['日期','有效分析用户交易量','其他用户交易量','平台总量','贡献占比'],tx.days.map(d=>[date(d.date),money(d.a),money(d.b),money(d.total),pct(d.a,d.total)]))}<p>北极星人数统计本期完成分析的人；交易贡献统计截至期末曾完成分析的人，包含本期没再分析的历史用户。</p><p>用户组在所选周期内固定，两组互斥。该指标表示用户群交易贡献，不证明分析促成交易；正式数据使用后台 user_id + date 日汇总。接口缺失显示待获取，不当作 0。</p></details></section>`}
function tradeDrill(tx,c,group,dateFilter=null){
const filtered=tx.records.filter(r=>r.volume>0&&(group==='a'?tx.analyzed.has(r.u.id):!tx.analyzed.has(r.u.id))&&(dateFilter===null||r.date===dateFilter));
const byUser=new Map();for(const r of filtered)byUser.set(r.u.id,(byUser.get(r.u.id)||0)+r.volume);
const total=filtered.reduce((n,r)=>n+r.volume,0),rows=[...byUser].sort((a,b)=>b[1]-a[1]).map(([id,volume])=>({u:users.find(u=>u.id===id)||{id,source:'未知'},volume}));
drawer.open({title:(group==='a'?'有效分析用户':'其他用户')+'交易贡献',description:(dateFilter===null?date(c.start)+'–'+date(c.end-day):date(dateFilter))+' · '+money(total),rows,columns:['用户','来源','交易量','占当前人群交易量'],renderRow:r=>[userButton(r.u),esc(r.u.source),money(r.volume),pct(r.volume,total)],onUser:userTimeline,note:'按交易量排序；后台每日汇总，不推断逐笔成交与分析先后。'});
}

function renderTrade(tx,c){if(!$('#as-trade-chart'))return;$$('[data-trade-group]').forEach(b=>b.onclick=()=>tradeDrill(tx,c,b.dataset.tradeGroup));const host=$('#as-trade-chart');if(!globalThis.echarts){host.innerHTML='<p class="a-muted">图表暂未加载，可展开每日交易明细查看。</p>';return}const color=key=>{const p=document.createElement('span');p.style.color=`var(${key})`;root.appendChild(p);const v=getComputedStyle(p).color;p.remove();return v};tradeChart=echarts.init(host,null,{renderer:'svg'});
const paint=()=>{if(!tradeChart||!host.isConnected)return;tradeChart.setOption({animation:false,aria:{enabled:true},legend:{top:12,data:['有效分析用户','其他用户'],textStyle:{color:color('--a-muted')}},tooltip:{trigger:'axis',confine:true,backgroundColor:color('--a-panel'),borderColor:color('--a-border'),textStyle:{color:color('--a-text')},formatter:p=>{const d=tx.days[p[0].dataIndex];return `${date(d.date)}<br/>有效分析用户：${money(d.a)}<br/>其他用户：${money(d.b)}<br/>平台总量：${money(d.total)}<br/>有效分析用户占比：${pct(d.a,d.total)}`}},grid:{top:66,left:64,right:15,bottom:30},xAxis:{type:'category',data:tx.days.map(d=>date(d.date)),axisLabel:{color:color('--a-muted')},axisLine:{lineStyle:{color:color('--a-border')}}},yAxis:{type:'value',name:'交易量（USD）',nameTextStyle:{color:color('--a-muted')},axisLabel:{color:color('--a-muted'),formatter:v=>v>=1000?(v/1000)+'k':v},splitLine:{lineStyle:{color:color('--a-border')}}},series:[{name:'有效分析用户',type:'bar',stack:'volume',barMaxWidth:34,itemStyle:{color:color('--a-accent')},data:tx.days.map(d=>d.a)},{name:'其他用户',type:'bar',stack:'volume',barMaxWidth:34,itemStyle:{color:color('--a-muted')},data:tx.days.map(d=>d.b)}]},true)};paint();tradeChart.on('click',p=>tradeDrill(tx,c,p.seriesIndex===0?'a':'b',tx.days[p.dataIndex].date));tradeResize=new ResizeObserver(()=>tradeChart&&tradeChart.resize());tradeResize.observe(host);tradeTheme=paint;themeMedia.addEventListener('change',tradeTheme)
}

function northPopulation(c,start=c.start,end=c.end){return users.filter(u=>{const first=u.events.find(e=>e.type==='chip');return first&&(c.source==='all'||first.entry_source===c.source)&&u.events.some(e=>e.type==='chip'&&e.t>=start&&e.t<end)})}
